import{_ as a,o as s,c as o,a2 as t}from"./chunks/framework.CQdiwDJy.js";const u=JSON.parse('{"title":"Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"en/reference/architecture.md","filePath":"en/reference/architecture.md","lastUpdated":1788601681000}'),n={name:"en/reference/architecture.md"};function i(r,e,c,l,d,p){return s(),o("div",null,[...e[0]||(e[0]=[t(`<h1 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h1><p>This is the human-facing deep dive. Agents: read <code>AGENTS/architecture.md</code> for the rulebook version (same facts, normative wording).</p><p>Tau is a pnpm workspace monorepo: <code>packages/</code> holds the capability layers, <code>app/</code> the front doors — all TypeScript ESM. The core principle is <strong>one-way dependencies</strong>: front doors depend on capability layers, and capability layers depend only downward.</p><h2 id="package-layout" tabindex="-1">Package layout <a class="header-anchor" href="#package-layout" aria-label="Permalink to &quot;Package layout&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>packages/</span></span>
<span class="line"><span>  core/      types, config, tool registry contracts (ToolDefinition / ToolResult)</span></span>
<span class="line"><span>  tools/     deterministic tool layer: file/sys/net/text families</span></span>
<span class="line"><span>  engine/    execution &amp; safety: reviewPlan() + runPlan() (the only channel)</span></span>
<span class="line"><span>  ai/        provider abstraction: AIProvider + seven implementations + streaming wire layer</span></span>
<span class="line"><span>  skills/    skill runtime + bundled user-facing skills (product content)</span></span>
<span class="line"><span>  plugins/   MCP client layer (plugin tools are ALWAYS medium risk)</span></span>
<span class="line"><span>  agent/     orchestration: catalog assembly + planning pipeline shared by ask/goal</span></span>
<span class="line"><span>  ui/ markdown/  terminal render primitives / dual-form markdown (HTML + ANSI)</span></span>
<span class="line"><span>app/</span></span>
<span class="line"><span>  cli/ tui/ webui/   three front doors, one engine, one gate</span></span></code></pre></div><h2 id="the-pipeline" tabindex="-1">The pipeline <a class="header-anchor" href="#the-pipeline" aria-label="Permalink to &quot;The pipeline&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>                 ┌──────────────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span> user intent ──► │ tau ask (app/cli/src/ask.ts)                                     │</span></span>
<span class="line"><span>                 │   1. resolveProvider()      packages/ai/src/registry.ts          │</span></span>
<span class="line"><span>                 │   2. planningContext()      packages/ai/src/prompt.ts            │</span></span>
<span class="line"><span>                 │      ├─ tool catalog  ←─ packages/tools/src/registry.ts         │</span></span>
<span class="line"><span>                 │      └─ skill catalog ←─ packages/skills/src/loader.ts          │</span></span>
<span class="line"><span>                 │   3. provider.plan()        packages/ai/src/providers/*          │</span></span>
<span class="line"><span>                 │      └─ validatePlanResponse()  zod, STRICT JSON                 │</span></span>
<span class="line"><span>                 │   4. runPlan()              packages/engine/src/session.ts       │</span></span>
<span class="line"><span>                 │      ├─ reviewPlan()        packages/engine/src/safety.ts        │</span></span>
<span class="line"><span>                 │      ├─ confirm UI          packages/ui/src/confirm.ts           │</span></span>
<span class="line"><span>                 │      ├─ executeStep()       packages/engine/src/executor.ts      │</span></span>
<span class="line"><span>                 │      └─ appendHistory()     packages/core/src/config/history.ts  │</span></span>
<span class="line"><span>                 └──────────────────────────────────────────────────────────────────┘</span></span>
<span class="line"><span></span></span>
<span class="line"><span> direct CLI (tau file find ...) ──► runToolDirect() ──► tool.run() ──► history</span></span>
<span class="line"><span> tui / webui (tau tui, tau web) ──► @tau/agent planIntent() ──► runPlan() ──┘</span></span></code></pre></div><p>Three invariants: (1) the AI never grades itself — review is deterministic code; (2) <code>runPlan()</code> is the only execution channel, no bypass; (3) plans are strict JSON — loose output is rejected.</p><h2 id="the-streaming-layer-v0-5-0" tabindex="-1">The streaming layer (v0.5.0) <a class="header-anchor" href="#the-streaming-layer-v0-5-0" aria-label="Permalink to &quot;The streaming layer (v0.5.0)&quot;">​</a></h2><p><code>packages/ai/src/chat-stream.ts</code> is the unified streaming wire layer: four wire protocols (OpenAI SSE, Anthropic Messages SSE, Gemini <code>alt=sse</code>, Ollama NDJSON) collapse into provider-agnostic <code>ProviderStreamEvent</code>s (<code>reasoning_delta</code> / <code>text_delta</code> / <code>usage</code>). The agent layer (<code>planIntentStream</code>, <code>runGoal</code>&#39;s <code>onPlanStream</code>) and the WebUI (<code>/api/plan/stream</code>, thinking panels) consume the same event shapes, relaying layer by layer without re-invention. Streaming is an optional capability: a provider without <code>planStream()</code>/<code>reflectStream()</code> falls back to buffered planning with zero behavior change, and a streamed plan still passes the same validation and review as a buffered one.</p><h2 id="module-tour" tabindex="-1">Module tour <a class="header-anchor" href="#module-tour" aria-label="Permalink to &quot;Module tour&quot;">​</a></h2><h3 id="packages-core-src-types-ts-—-the-vocabulary" tabindex="-1">packages/core/src/types.ts — the vocabulary <a class="header-anchor" href="#packages-core-src-types-ts-—-the-vocabulary" aria-label="Permalink to &quot;packages/core/src/types.ts — the vocabulary&quot;">​</a></h3><p>Every subsystem speaks the same language: <code>Plan</code>, <code>PlanStep</code>, <code>ToolDefinition</code>, <code>SkillMeta</code>, <code>SafetyReview</code>, <code>RiskLevel</code> (low &lt; medium &lt; high &lt; blocked). Since v0.5.0 the vocabulary also carries the streaming shapes — <code>ProviderStreamEvent</code>, <code>ProviderUsage</code>, and the optional <code>planStream</code>/<code>reflectStream</code> capability methods on <code>AIProvider</code>. Change these and the typechecker will walk you through the consequences.</p><h3 id="packages-tools-src-—-the-dual-use-toolbelt" tabindex="-1">packages/tools/src/ — the dual-use toolbelt <a class="header-anchor" href="#packages-tools-src-—-the-dual-use-toolbelt" aria-label="Permalink to &quot;packages/tools/src/ — the dual-use toolbelt&quot;">​</a></h3><p>A <code>ToolDefinition</code> is both a CLI backend and a unit the AI planner can propose. Tools return plain text (no ANSI — history must stay clean) and may throw; callers render errors. Registration is idempotent for core tools and throw-on-duplicate for skills (shadowing a core tool must fail loudly).</p><p>Families: <code>file.*</code>, <code>sys.*</code>, <code>net.*</code>, <code>text.*</code>. Design bias: read-only by default; the mutating tools (<code>file.rename</code>, <code>text.replace</code>, <code>file.write</code>) are dry-run by default and carry <code>risk: medium</code>.</p><h3 id="packages-engine-src-safety-ts-—-the-deterministic-gate" tabindex="-1">packages/engine/src/safety.ts — the deterministic gate <a class="header-anchor" href="#packages-engine-src-safety-ts-—-the-deterministic-gate" aria-label="Permalink to &quot;packages/engine/src/safety.ts — the deterministic gate&quot;">​</a></h3><p>Two pattern lists: <code>DENY_PATTERNS</code> (verdict: deny) and <code>CAUTION_PATTERNS</code> (escalate to high risk). Plus structural rules: no steps, &gt;10 steps, unknown tool references, empty shell commands, &gt;2000-char shell commands → blocked. The reviewer is pure: same plan in, same verdict out, no network, no clock.</p><h3 id="packages-engine-src-session-ts-—-the-only-door-to-execution" tabindex="-1">packages/engine/src/session.ts — the only door to execution <a class="header-anchor" href="#packages-engine-src-session-ts-—-the-only-door-to-execution" aria-label="Permalink to &quot;packages/engine/src/session.ts — the only door to execution&quot;">​</a></h3><p><code>runPlan()</code> orchestrates review → confirm → execute → history. Anything that runs AI-generated steps goes through it. Direct CLI tool runs bypass confirmation (first-party code) but never bypass history.</p><h3 id="packages-ai-src-—-providers-behind-one-interface" tabindex="-1">packages/ai/src/ — providers behind one interface <a class="header-anchor" href="#packages-ai-src-—-providers-behind-one-interface" aria-label="Permalink to &quot;packages/ai/src/ — providers behind one interface&quot;">​</a></h3><p><code>AIProvider.plan(ctx) -&gt; Plan</code>. Providers receive the REAL tool+skill catalog in the system prompt, so they can only propose things that exist — and the reviewer independently re-verifies that. <code>validatePlanResponse()</code> is strict about content (zod <code>.strict()</code>), tolerant about wrapping (code fences, prose).</p><p>Providers: <code>mock</code> (offline keyword matching), <code>ollama</code> (local HTTP), <code>openai</code> (any OpenAI-compatible endpoint), <code>deepseek</code> (official streaming wire format, harness adapter with zero-dep fallback), <code>zai</code> (optional SDK, dynamically imported), <code>anthropic</code> (Messages API with native thinking blocks), <code>gemini</code> (GenerateContent with thought parts).</p><p>Providers may also implement <code>listModels()</code> for live model discovery. The catalog service (<code>packages/ai/src/models.ts</code>) caches ids per provider (24 h TTL) and the <code>tau provider</code> command family (set-key / models / use) turns it into the model-selection UX: configuring an API key auto-refreshes the catalog, then you pick from real models. There are no bundled default models — with a single-model catalog Tau auto-selects it, otherwise selection is explicit (<code>tau provider use</code>) and the request-time resolver (<code>resolveModel</code>) fails with an actionable hint when nothing is chosen. Keys live in config (chmod 0600) with env vars as fallback and are masked in every CLI output.</p><h3 id="packages-skills-src-—-markdown-as-a-plugin-format" tabindex="-1">packages/skills/src/ — markdown as a plugin format <a class="header-anchor" href="#packages-skills-src-—-markdown-as-a-plugin-format" aria-label="Permalink to &quot;packages/skills/src/ — markdown as a plugin format&quot;">​</a></h3><p>SKILL.md frontmatter (yaml + zod) → <code>SkillMeta</code>. Declarative <code>commands</code> become tools named <code>&lt;skill&gt;.&lt;command&gt;</code> at startup. Three scopes with later-wins precedence: bundled → user ($TAU_HOME/skills) → workspace (./skills, ./.tau/skills). Skills are data: nothing in a skill directory is ever <code>eval</code>&#39;d or dynamically imported.</p><h3 id="packages-core-src-config-—-where-state-lives" tabindex="-1">packages/core/src/config/ — where state lives <a class="header-anchor" href="#packages-core-src-config-—-where-state-lives" aria-label="Permalink to &quot;packages/core/src/config/ — where state lives&quot;">​</a></h3><p><code>$TAU_HOME</code> (default <code>~/.tau</code>, XDG-aware, overridable for tests): <code>config.json</code> (provider, timeout, aliases, per-provider settings — may hold API keys, so it is written with chmod 0600 and keys are masked on display), <code>history.jsonl</code> (append-only, one <code>HistoryEntry</code> per line).</p><h2 id="directory-governance" tabindex="-1">Directory governance <a class="header-anchor" href="#directory-governance" aria-label="Permalink to &quot;Directory governance&quot;">​</a></h2><p>The normative table is in <code>AGENTS/architecture.md</code>; the short version:</p><ul><li><strong>Repo root</strong>: <code>AGENTS.md</code> + <code>AGENTS/</code> (AI behavior rulebooks), <code>SKILL.md</code> (the root dev-tool skill router — top of the SKILL.md read chain), <code>.claude/skills/</code> (root-layer dev-workflow SKILL.md files for coding agents — tau-skill-new is a thin router), <code>docs/</code> (the VitePress documentation site — this site), <code>.github/</code>, <code>scripts/</code> (workspace tooling incl. <code>scripts/screenshot/</code>; run-screenshot captures live in each app&#39;s <code>docs/screenshots/</code>). Package- and app-bound agent skills live at <code>packages/&lt;pkg&gt;/SKILL.md</code> and <code>app/&lt;app&gt;/SKILL.md</code> (tool layer — today: <code>packages/skills/SKILL.md</code> and <code>app/webui/SKILL.md</code>).</li><li><strong><code>packages/skills/</code></strong>: <code>bundled/&lt;name&gt;/SKILL.md</code> (skills that ship with the CLI, resolved at runtime via <code>packageRoot()</code>) and <code>templates/</code> (the <code>tau skill new</code> scaffold, read at runtime) — these are product content (runtime data for the CLI), not agent skills.</li><li><strong>Runtime, never committed</strong>: <code>$TAU_HOME/skills/</code> (user skills), <code>config.json</code>, <code>history.jsonl</code>; plus the <em>user&#39;s</em> project <code>./skills/</code> / <code>./.tau/skills/</code> scopes. Tau&#39;s own repo never contains user-scope skills.</li></ul><p><code>docs/</code> is a PRIVATE workspace member (<code>@tau/docs</code>) — the docs are content, never runtime data; the CLI does not read from here.</p><h2 id="invariants" tabindex="-1">Invariants <a class="header-anchor" href="#invariants" aria-label="Permalink to &quot;Invariants&quot;">​</a></h2><ol><li><code>runPlan()</code> is the single execution path for AI plans.</li><li><code>blocked</code> risk is terminal — no flag or config downgrades it.</li><li>Mutating tools dry-run by default.</li><li>The planner sees exactly what the reviewer will enforce.</li><li>History records everything that touched the world.</li></ol><h2 id="extending" tabindex="-1">Extending <a class="header-anchor" href="#extending" aria-label="Permalink to &quot;Extending&quot;">​</a></h2><ul><li><strong>New tool op</strong> → <code>packages/tools/src/&lt;family&gt;.ts</code> (ToolDefinition) + CLI wiring in <code>app/cli/src/&lt;family&gt;.ts</code> + tests. Mutating? Make it dry-run default.</li><li><strong>New provider</strong> → <code>packages/ai/src/providers/&lt;name&gt;.ts</code> + registry + config defaults <ul><li>tests with mocked fetch. Adding streaming? Implement <code>planStream()</code> on the wire protocol, or fall back to buffered <code>plan()</code>. See <a href="/Tau/en/reference/provider-dev.html">provider development</a>.</li></ul></li><li><strong>New skill</strong> → just markdown; see the <a href="/Tau/en/guide/skills.html">skills guide</a>.</li></ul><p>Full &quot;I want to...&quot; table lives in <code>AGENTS/architecture.md</code>.</p>`,37)])])}const g=a(n,[["render",i]]);export{u as __pageData,g as default};
